checkRuns.command:
cat > src/routes/contact.kay <<'EOF'
--- server
import { t } from 'kay'
import { validateContact } from '../contact'
import ContactForm from '../components/contact-form.kay'

export const send = action(t.Object({ name: t.String(), email: t.String(), message: t.String() }), ({ name, email, message }, ctx) => {
  const errors = validateContact({ name, email, message })

  if (Object.keys(errors).length > 0)
    return ctx.fail(422, { errors })

  return { name: name.trim() }
})

const failed = ctx.failed(send)
const succeeded = ctx.succeeded(send)
const values = { name: failed?.values.name ?? '', email: failed?.values.email ?? '', message: failed?.values.message ?? '' }
const errors = failed?.data.errors ?? {}
const sentName = succeeded?.data.name
---
head
  title Contact
h1 Contact
ContactForm(values={values} errors={errors} sentName={sentName})
EOF
cat > src/components/contact-form.kay <<'EOF'
---
import { send } from '../routes/contact.kay'
import { validateContact } from '../contact'
import type { ContactErrors, ContactValues } from '../contact'

const { values, errors: initialErrors, sentName } = props<{ values: ContactValues, errors: ContactErrors, sentName?: string }>()
const name = signal(values.name)
const email = signal(values.email)
const message = signal(values.message)
const errors = signal<ContactErrors>(initialErrors)
const sent = signal<string | undefined>(sentName)

async function submit(event: SubmitEvent) {
  const form = event.currentTarget as HTMLFormElement
  event.preventDefault()
  sent.set(undefined)

  const found = validateContact({ name: name(), email: email(), message: message() })
  errors.set(found)

  if (Object.keys(found).length > 0)
    return

  try {
    const result = await send(new FormData(form), { refresh: false })
    sent.set(result.name)
    name.set('')
    email.set('')
    message.set('')
  }
  catch {
    errors.set({ message: 'Could not send your message.' })
  }
}
---
if sent
  p.success Thanks, {sent}! Your message has been sent.
form(action={send} method="post" novalidate onSubmit={submit})
  div
    label(for="contact-name") Name
    input#contact-name(type="text" name="name" bind:value={name})
    if errors.name
      span.error {errors.name}
  div
    label(for="contact-email") Email
    input#contact-email(type="email" name="email" bind:value={email})
    if errors.email
      span.error {errors.email}
  div
    label(for="contact-message") Message
    textarea#contact-message(name="message" bind:value={message})
    if errors.message
      span.error {errors.message}
  button(type="submit") Send
EOF
